/**
 * AttendanceSummary Page (Admin)
 * Displays a summary of all students' attendance by class and by student
 * Features: Sorting, Search/Filter, and Pagination
 */

import React, { useState, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
  CheckCircle,
  XCircle,
  Clock,
  AlertCircle,
  ClockAlert,
  Users,
  Calendar,
  Loader2,
  TrendingUp,
  Filter,
  User as UserIcon,
  ChevronDown,
  ChevronUp,
  Download,
  X,
} from 'lucide-react';
import { apiService } from '@/services/api';
import { useTranslation } from '@/contexts/LanguageContext';
import type {
  ClassAttendanceSummary,
  StudentAttendanceSummary,
  OverallAttendanceStats,
} from '@/types';

type TabType = 'by-class' | 'by-student';

type SortFieldClass = 'class_name' | 'course_name' | 'attendance' | 'students' | 'meetings' | 'percentage';
type SortFieldStudent = 'name' | 'nim' | 'program' | 'percentage' | 'classes_count';
type SortField = SortFieldClass | SortFieldStudent;
type SortOrder = 'asc' | 'desc';

interface PaginationParams {
  page: number;
  limit: number;
  total: number;
}

const AttendanceSummary: React.FC = () => {
  const { t } = useTranslation();
  const [activeTab, setActiveTab] = useState<TabType>('by-class');
  const [selectedSemester, setSelectedSemester] = useState<string>('');
  const [selectedProgram, setSelectedProgram] = useState<string>('');

  // Sorting state
  const [sortField, setSortField] = useState<SortField>('class_name');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  // Pagination state
  const [pagination, setPagination] = useState<PaginationParams>({
    page: 1,
    limit: 20,
    total: 0,
  });

  // Search state for by-student tab
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Fetch attendance summary using the dedicated API endpoint
  const { data: summaryData, isLoading, error, refetch } = useQuery({
    queryKey: ['admin-attendance-summary', selectedSemester, selectedProgram],
    queryFn: async () => {
      return await apiService.getAttendanceSummary({
        semester: selectedSemester || undefined,
        program: selectedProgram || undefined,
      });
    },
    enabled: true,
  });

  // Get overall stats
  const overallStats = summaryData?.overall_stats as OverallAttendanceStats | undefined;

  // Process and sort data for By Class tab
  const byClassData = useMemo(() => {
    const data = summaryData?.by_class || [];

    // Sort data
    const sorted = [...data].sort((a: ClassAttendanceSummary, b: ClassAttendanceSummary) => {
      let comparison = 0;

      switch (sortField as SortFieldClass) {
        case 'class_name':
          comparison = (a.class_name || '').localeCompare(b.class_name || '');
          break;
        case 'course_name':
          comparison = (a.course_name || '').localeCompare(b.course_name || '');
          break;
        case 'attendance':
          comparison = (b.percentage - 0) - (a.percentage - 0);
          break;
        case 'students':
          comparison = (a.total_students || 0) - (b.total_students || 0);
          break;
        case 'meetings':
          comparison = (a.total_meetings || 0) - (b.total_meetings || 0);
          break;
        case 'percentage':
          comparison = (b.percentage || 0) - (a.percentage || 0);
          break;
        default:
          comparison = 0;
      }

      return sortOrder === 'asc' ? comparison : -comparison;
    });

    // Update pagination total
    setPagination((prev) => ({ ...prev, total: sorted.length }));

    return sorted;
  }, [summaryData?.by_class, sortField, sortOrder]);

  // Process and sort data for By Student tab
  const byStudentData = useMemo(() => {
    const data = summaryData?.by_student || [];

    // Apply search filter first
    let filtered = data;
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = data.filter((student: StudentAttendanceSummary) => {
        return (
          student.name.toLowerCase().includes(query) ||
          student.nim.toLowerCase().includes(query)
        );
      });
    }

    // Sort filtered data
    const sorted = [...filtered].sort((a: StudentAttendanceSummary, b: StudentAttendanceSummary) => {
      let comparison = 0;

      switch (sortField as SortFieldStudent) {
        case 'name':
          comparison = a.name.localeCompare(b.name);
          break;
        case 'nim':
          comparison = a.nim.localeCompare(b.nim);
          break;
        case 'program':
          comparison = (a.program || '').localeCompare(b.program || '');
          break;
        case 'percentage':
          comparison = b.overall_percentage - a.overall_percentage;
          break;
        case 'classes_count':
          comparison = a.classes.length - b.classes.length;
          break;
        default:
          comparison = 0;
      }

      return sortOrder === 'asc' ? comparison : -comparison;
    });

    // Update pagination total
    setPagination((prev) => ({ ...prev, total: sorted.length }));

    return sorted;
  }, [summaryData?.by_student, sortField, sortOrder, searchQuery]);

  // Get current tab's data
  const currentData = activeTab === 'by-class' ? byClassData : byStudentData;

  // Calculate pagination
  const totalPages = useMemo(() => {
    if (currentData.length === 0) return 1;
    return Math.ceil(currentData.length / pagination.limit);
  }, [currentData.length, pagination.limit]);

  // Paginate data
  const paginatedData = useMemo(() => {
    const startIndex = (pagination.page - 1) * pagination.limit;
    const endIndex = startIndex + pagination.limit;
    return currentData.slice(startIndex, endIndex);
  }, [currentData, pagination.page, pagination.limit]);

  const getSortIcon = (field: SortField, _currentTab: TabType) => {
    const isSorted = sortField === field;
    return (
      <button
        onClick={() => handleSort(field)}
        className={`flex items-center gap-1 ${
          isSorted ? 'text-blue-600' : 'text-gray-400'
        } hover:text-blue-800`}
        title={`Sort by ${field} (${sortOrder === 'asc' ? 'ascending' : 'descending'})`}
      >
        {sortOrder === 'asc' ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
      </button>
    );
  };

  const getAttendanceColor = (percentage: number): string => {
    if (percentage >= 80) return 'text-green-600 bg-green-50';
    if (percentage >= 70) return 'text-yellow-600 bg-yellow-50';
    return 'text-red-600 bg-red-50';
  };

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  const handlePageChange = (newPage: number) => {
    setPagination((prev) => ({
      ...prev,
      page: newPage,
    }));
  };

  const handleExportCSV = () => {
    if (currentData.length === 0) return;

    let csvContent: string[][] = [];

    if (activeTab === 'by-class') {
      csvContent = [
        ['Class ID', 'Class Name', 'Course Code', 'Course Name', 'Students', 'Meetings', 'Hadir', 'Izin', 'Sakit', 'Terlambat', 'Alfa', 'Attendance %'],
        ...(currentData as ClassAttendanceSummary[]).map((cls) => [
          String(cls.class_id),
          cls.class_name,
          cls.course_code,
          cls.course_name,
          String(cls.total_students),
          String(cls.total_meetings),
          String(cls.attended),
          String(cls.excused),
          String(cls.sick),
          String(cls.late),
          String(cls.absent),
          `${cls.percentage.toFixed(1)}%`,
        ]),
      ];
    } else {
      // Collect all unique course codes
      const allCourses = new Set<string>();
      (currentData as StudentAttendanceSummary[]).forEach((student) => {
        student.classes.forEach((cls) => {
          allCourses.add(cls.course_code);
        });
      });
      const courseColumns = Array.from(allCourses).sort();

      csvContent = [
        ['NIM', 'Name', 'Program', 'Overall %', 'Total Classes', ...courseColumns.flatMap(c => [`${c} Attended`, `${c} Total`, `${c} %`])],
        ...(currentData as StudentAttendanceSummary[]).map((student) => {
          const classMap = new Map(student.classes.map((cls) => [cls.course_code, cls]));
          return [
            student.nim,
            student.name,
            student.program,
            `${student.overall_percentage.toFixed(1)}%`,
            String(student.classes.length),
            ...courseColumns.flatMap((code) => {
              const cls = classMap.get(code);
              return cls ? [String(cls.attended), String(cls.total_meetings), `${cls.percentage.toFixed(1)}%`] : ['', '', ''];
            }),
          ];
        }),
      ];
    }

    const csvString = csvContent.map((row) => row.join(',')).join('\n');
    const blob = new Blob([csvString], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `attendance-summary-${activeTab}-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  if (isLoading) {
    return (
      <div className="flex flex-col items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
        <p className="text-gray-600 mt-4">Loading attendance summary...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="space-y-6">
        <div className="bg-red-50 border border-red-200 rounded-lg p-4">
          <p className="text-red-800">Error loading attendance summary: {(error as Error).message}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">{t('sidebar.attendanceSummary')}</h1>
          <p className="text-gray-600 mt-1">Overview of student attendance by class and student</p>
        </div>
      </div>

      {/* Filters */}
      <div className="card p-4">
        <div className="flex flex-wrap gap-4 items-center">
          <Filter className="h-5 w-5 text-gray-400" />
          <div className="flex-1 min-w-[200px]">
            <label className="block text-sm font-medium text-gray-700 mb-1">Semester</label>
            <input
              type="text"
              placeholder="e.g., 2024-2025 Ganjil"
              value={selectedSemester}
              onChange={(e) => setSelectedSemester(e.target.value)}
              className="input-field"
            />
          </div>
          <div className="flex-1 min-w-[200px]">
            <label className="block text-sm font-medium text-gray-700 mb-1">Program</label>
            <input
              type="text"
              placeholder="e.g., IF"
              value={selectedProgram}
              onChange={(e) => setSelectedProgram(e.target.value)}
              className="input-field"
            />
          </div>
          {activeTab === 'by-student' && (
            <div className="flex-1 min-w-[300px]">
              <label className="block text-sm font-medium text-gray-700 mb-1">Search Students</label>
              <div className="relative">
                <UserIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
                <input
                  type="text"
                  placeholder="Search by name or NIM..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="input-field pl-10"
                />
                {searchQuery && (
                  <button
                    onClick={() => setSearchQuery('')}
                    className="absolute right-3 top-1/2 p-1 text-gray-400 hover:text-gray-600"
                    title="Clear search"
                  >
                    <X className="h-4 w-4" />
                  </button>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Overall Stats Cards */}
      {overallStats && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className={`card p-4 border-l-4 ${getAttendanceColor(overallStats.average_attendance)}`}>
            <div className="flex items-center gap-4">
              <div className="bg-blue-100 p-3 rounded-lg">
                <TrendingUp className="h-6 w-6 text-blue-600" />
              </div>
              <div>
                <p className="text-sm text-gray-600">Average Attendance</p>
                <p className="text-2xl font-bold text-gray-900">{overallStats.average_attendance.toFixed(1)}%</p>
              </div>
            </div>
          </div>

          <div className="card p-4">
            <div className="flex items-center gap-4">
              <div className="bg-green-100 p-3 rounded-lg">
                <Users className="h-6 w-6 text-green-600" />
              </div>
              <div>
                <p className="text-sm text-gray-600">Total Students</p>
                <p className="text-2xl font-bold text-gray-900">{overallStats.total_students}</p>
              </div>
            </div>
          </div>

          <div className="card p-4">
            <div className="flex items-center gap-4">
              <div className="bg-purple-100 p-3 rounded-lg">
                <Calendar className="h-6 w-6 text-purple-600" />
              </div>
              <div>
                <p className="text-sm text-gray-600">Total Classes</p>
                <p className="text-2xl font-bold text-gray-900">{overallStats.total_classes}</p>
              </div>
            </div>
          </div>

          <div className="card p-4">
            <div className="flex items-center gap-4">
              <div className="bg-orange-100 p-3 rounded-lg">
                <Calendar className="h-6 w-6 text-orange-600" />
              </div>
              <div>
                <p className="text-sm text-gray-600">Total Meetings</p>
                <p className="text-2xl font-bold text-gray-900">{overallStats.total_meetings}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Action Bar */}
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">
            {activeTab === 'by-class' ? 'Class Attendance' : 'Student Attendance'}
          </h2>
          <p className="text-sm text-gray-500">
            Showing {currentData.length} {activeTab === 'by-class' ? 'classes' : 'students'}
          </p>
        </div>

        <div className="flex gap-2">
          {/* Export Button */}
          <button
            onClick={handleExportCSV}
            className="btn-secondary flex items-center gap-2"
            disabled={currentData.length === 0}
            title={`Export ${activeTab === 'by-class' ? 'Classes' : 'Students'} to CSV`}
          >
            <Download className="h-4 w-4" />
            <span>Export CSV</span>
          </button>

          {/* Refresh Button */}
          <button
            onClick={() => refetch()}
            className="btn-secondary flex items-center gap-2"
            title="Refresh data"
          >
            <Users className="h-4 w-4" />
            <span>Refresh</span>
          </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="card">
        <div className="border-b border-gray-200">
          <nav className="flex space-x-8" aria-label="Tabs">
            <button
              onClick={() => {
                setActiveTab('by-class');
                setPagination((prev) => ({ ...prev, page: 1 }));
                setSortField('class_name');
              }}
              className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === 'by-class'
                  ? 'border-blue-600 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              By Class
            </button>
            <button
              onClick={() => {
                setActiveTab('by-student');
                setPagination((prev) => ({ ...prev, page: 1 }));
                setSortField('name');
              }}
              className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${
                activeTab === 'by-student'
                  ? 'border-blue-600 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              By Student
            </button>
          </nav>
        </div>

        {/* Tab Content - By Class */}
        {activeTab === 'by-class' && (
          <div className="p-6">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center gap-1">Class {getSortIcon('class_name', 'by-class')}</div>
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center gap-1">Course Name {getSortIcon('course_name', 'by-class')}</div>
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center justify-center gap-1">Students {getSortIcon('students', 'by-class')}</div>
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center justify-center gap-1">Meetings {getSortIcon('meetings', 'by-class')}</div>
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center justify-center gap-1">Attendance {getSortIcon('percentage', 'by-class')}</div>
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Breakdown
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {(paginatedData as ClassAttendanceSummary[]).map((cls, idx) => (
                    <tr key={cls.class_id} className={idx === 0 ? 'border-t border-gray-300' : ''}>
                      <td className="px-4 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">{cls.class_name}</div>
                      </td>
                      <td className="px-4 py-4">
                        <div className="text-sm text-gray-900">{cls.course_name}</div>
                        <div className="text-xs text-gray-500">{cls.course_code}</div>
                      </td>
                      <td className="px-4 py-4 text-center text-sm text-gray-900">{cls.total_students}</td>
                      <td className="px-4 py-4 text-center text-sm text-gray-900">{cls.total_meetings}</td>
                      <td className="px-4 py-4 text-center">
                        <span className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-bold ${getAttendanceColor(cls.percentage)}`}>
                          {cls.percentage.toFixed(1)}%
                        </span>
                      </td>
                      <td className="px-4 py-4">
                        <div className="flex items-center justify-center gap-2 text-xs flex-wrap">
                          {cls.attended > 0 && (
                            <span className="flex items-center gap-1 text-green-600" title="Hadir (Present)">
                              <CheckCircle className="h-3 w-3" /> {cls.attended}
                            </span>
                          )}
                          {cls.excused > 0 && (
                            <span className="flex items-center gap-1 text-blue-600" title="Izin (Excused)">
                              <Clock className="h-3 w-3" /> {cls.excused}
                            </span>
                          )}
                          {cls.sick > 0 && (
                            <span className="flex items-center gap-1 text-yellow-600" title="Sakit (Sick)">
                              <AlertCircle className="h-3 w-3" /> {cls.sick}
                            </span>
                          )}
                          {cls.late > 0 && (
                            <span className="flex items-center gap-1 text-orange-600" title="Terlambat (Late)">
                              <ClockAlert className="h-3 w-3" /> {cls.late}
                            </span>
                          )}
                          {cls.absent > 0 && (
                            <span className="flex items-center gap-1 text-red-600" title="Alfa (Absent)">
                              <XCircle className="h-3 w-3" /> {cls.absent}
                            </span>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Tab Content - By Student */}
        {activeTab === 'by-student' && (
          <div className="p-6">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center gap-1">NIM {getSortIcon('nim', 'by-student')}</div>
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center gap-1">Name {getSortIcon('name', 'by-student')}</div>
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center gap-1">Program {getSortIcon('program', 'by-student')}</div>
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center justify-center gap-1">Classes {getSortIcon('classes_count', 'by-student')}</div>
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      <div className="flex items-center justify-center gap-1">Overall {getSortIcon('percentage', 'by-student')}</div>
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider min-w-[400px]">
                      Class Details
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {(paginatedData as StudentAttendanceSummary[]).map((student, idx) => (
                    <tr key={student.nim} className={idx === 0 ? 'border-t border-gray-300' : ''}>
                      <td className="px-4 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">{student.nim}</div>
                      </td>
                      <td className="px-4 py-4">
                        <div className="text-sm text-gray-900">{student.name}</div>
                      </td>
                      <td className="px-4 py-4">
                        <span className="px-2 py-1 text-xs font-medium rounded bg-gray-100 text-gray-700">
                          {student.program}
                        </span>
                      </td>
                      <td className="px-4 py-4 text-center text-sm text-gray-900">{student.classes.length}</td>
                      <td className="px-4 py-4 text-center">
                        <span className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-bold ${getAttendanceColor(student.overall_percentage)}`}>
                          {student.overall_percentage.toFixed(1)}%
                        </span>
                      </td>
                      <td className="px-4 py-4">
                        <div className="space-y-1">
                          {student.classes.map((cls) => (
                            <div key={cls.class_id} className="space-y-1">
                              <div className="flex items-center gap-2 text-xs">
                                <div className="flex-1">
                                  <span className="font-medium text-gray-900">{cls.course_code}</span>
                                  <span className="text-gray-500 ml-1">-</span>
                                  <span className="text-gray-600">{cls.course_name}</span>
                                </div>
                                <div className="flex items-center gap-1">
                                  <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-semibold ${getAttendanceColor(cls.percentage)}`}>
                                    {cls.percentage.toFixed(1)}%
                                  </span>
                                </div>
                              </div>
                              {/* Attendance breakdown */}
                              <div className="flex items-center gap-2 text-xs pl-2">
                                {cls.excused !== undefined || cls.sick !== undefined || cls.late !== undefined || cls.absent !== undefined || cls.substitute !== undefined ? (
                                  <>
                                    {cls.attended > 0 && (
                                      <span className="flex items-center gap-1 text-green-600" title="Hadir (Present)">
                                        <CheckCircle className="h-3 w-3" /> {cls.attended}
                                      </span>
                                    )}
                                    {cls.excused !== undefined && cls.excused > 0 && (
                                      <span className="flex items-center gap-1 text-blue-600" title="Izin (Excused)">
                                        <Clock className="h-3 w-3" /> {cls.excused}
                                      </span>
                                    )}
                                    {cls.sick !== undefined && cls.sick > 0 && (
                                      <span className="flex items-center gap-1 text-yellow-600" title="Sakit (Sick)">
                                        <AlertCircle className="h-3 w-3" /> {cls.sick}
                                      </span>
                                    )}
                                    {cls.late !== undefined && cls.late > 0 && (
                                      <span className="flex items-center gap-1 text-orange-600" title="Terlambat (Late)">
                                        <ClockAlert className="h-3 w-3" /> {cls.late}
                                      </span>
                                    )}
                                    {cls.substitute !== undefined && cls.substitute > 0 && (
                                      <span className="flex items-center gap-1 text-purple-600" title="Pengganti (Substitute)">
                                        <CheckCircle className="h-3 w-3" /> {cls.substitute}
                                      </span>
                                    )}
                                    {cls.absent !== undefined && cls.absent > 0 && (
                                      <span className="flex items-center gap-1 text-red-600" title="Alfa (Absent)">
                                        <XCircle className="h-3 w-3" /> {cls.absent}
                                      </span>
                                    )}
                                    {(cls.absent !== undefined || cls.substitute !== undefined) && (
                                      <>
                                        <span className="text-gray-400">/</span>
                                        <span className="text-gray-600">{cls.total_meetings}</span>
                                      </>
                                    )}
                                  </>
                                ) : (
                                  <span className="text-gray-600" title="Hadir">
                                    ✓{cls.attended} / {cls.total_meetings}
                                  </span>
                                )}
                              </div>
                            </div>
                          ))}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-6 py-4 border-t border-gray-200">
            <div className="flex items-center justify-between">
              <div className="text-sm text-gray-600">
                Showing {(pagination.page - 1) * pagination.limit + 1} to{' '}
                {Math.min(pagination.page * pagination.limit, currentData.length)} of {currentData.length} results
              </div>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => handlePageChange(pagination.page - 1)}
                  disabled={pagination.page === 1}
                  className="px-3 py-1 border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed text-sm"
                >
                  Previous
                </button>
                <span className="text-sm text-gray-600">
                  Page {pagination.page} of {totalPages}
                </span>
                <button
                  onClick={() => handlePageChange(pagination.page + 1)}
                  disabled={pagination.page === totalPages}
                  className="px-3 py-1 border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed text-sm"
                >
                  Next
                </button>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Legend */}
      <div className="card p-4">
        <div className="flex items-center gap-6 text-sm text-gray-600 flex-wrap">
          <span className="font-medium text-gray-700">Legend:</span>
          <div className="flex items-center gap-1">
            <CheckCircle className="h-4 w-4 text-green-600" />
            <span>Present (Hadir)</span>
          </div>
          <div className="flex items-center gap-1">
            <Clock className="h-4 w-4 text-blue-600" />
            <span>Excused (Izin)</span>
          </div>
          <div className="flex items-center gap-1">
            <AlertCircle className="h-4 w-4 text-yellow-600" />
            <span>Sick (Sakit)</span>
          </div>
          <div className="flex items-center gap-1">
            <ClockAlert className="h-4 w-4 text-orange-600" />
            <span>Late (Terlambat)</span>
          </div>
          <div className="flex items-center gap-1">
            <CheckCircle className="h-4 w-4 text-red-600" />
            <span>Absent (Alfa)</span>
          </div>
          <div className="flex items-center gap-1">
            <CheckCircle className="h-4 w-4 text-purple-600" />
            <span>Substitute (Pengganti)</span>
          </div>
          <div className="w-px h-4 bg-gray-300 mx-2"></div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-green-100"></div>
            <span className="text-green-600">Good (≥80%)</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-yellow-100"></div>
            <span className="text-yellow-600">Warning (≥70%)</span>
          </div>
          <div className="flex items-center gap-1">
            <div className="w-3 h-3 rounded-full bg-red-100"></div>
            <span className="text-red-600">Poor (&lt;70%)</span>
          </div>
        </div>
      </div>

      {/* Empty State */}
      {!isLoading && currentData.length === 0 && (
        <div className="text-center py-12 card">
          <Calendar className="mx-auto h-12 w-12 text-gray-400 mb-4" />
          <p className="text-gray-500 text-lg">No attendance data found</p>
          <p className="text-gray-400 text-sm mt-2">
            {searchQuery ? 'Try adjusting your search query' : 'Try adjusting filters or check if classes have been created'}
          </p>
        </div>
      )}
    </div>
  );
};

export default AttendanceSummary;
